// Copies the skills in plugin/skills and the server schema into
// lib/embedded.g.dart, so the installed `todo` command can hand them out
// without the repository. Run from `cli` after changing either:
//
//   dart run tool/embed_skills.dart
import 'dart:io';

String _literal(String text) {
  final escaped = text
      .replaceAll(r'\', r'\\')
      .replaceAll(r'$', r'\$')
      .replaceAll("'", r"\'")
      .replaceAll('\r', '')
      .replaceAll('\n', r'\n');
  return "'$escaped'";
}

/// The generated file's contents, from the files as they are now.
String embedded() {
  final skills = Directory('../plugin/skills').listSync().whereType<Directory>().toList()
    ..sort((a, b) => a.path.compareTo(b.path));
  final out = StringBuffer()
    ..writeln('// Generated by tool/embed_skills.dart. Do not edit; run it again.')
    ..writeln()
    ..writeln('/// The skills in plugin/skills, by name: what an assistant reads to do a job.')
    ..writeln('const skills = <String, String>{');
  for (final dir in skills) {
    final name = dir.uri.pathSegments.where((s) => s.isNotEmpty).last;
    out.writeln("  '$name': ${_literal(File('${dir.path}/SKILL.md').readAsStringSync())},");
  }
  out
    ..writeln('};')
    ..writeln()
    ..writeln('/// supabase/schema.sql: what a new sync server is set up with.')
    ..writeln('const schemaSql = ${_literal(File('../supabase/schema.sql').readAsStringSync())};');
  return out.toString();
}

void main() {
  File('lib/embedded.g.dart').writeAsStringSync(embedded());
  stdout.writeln('Wrote lib/embedded.g.dart');
}
